-- v242 Homepage Studio: D1-backed homepage blocks (seeded with the exact current index.html items)
CREATE TABLE IF NOT EXISTS homepage_blocks (
  id TEXT PRIMARY KEY,
  section_key TEXT NOT NULL,
  title_en TEXT NOT NULL DEFAULT '',
  title_or TEXT NOT NULL DEFAULT '',
  subtitle_en TEXT NOT NULL DEFAULT '',
  subtitle_or TEXT NOT NULL DEFAULT '',
  badge_en TEXT NOT NULL DEFAULT '',
  icon TEXT NOT NULL DEFAULT '',
  href TEXT NOT NULL DEFAULT '',
  cta_label_en TEXT NOT NULL DEFAULT '',
  cta_label_or TEXT NOT NULL DEFAULT '',
  accent_variant TEXT NOT NULL DEFAULT '',
  sort_order INTEGER NOT NULL DEFAULT 0,
  is_published INTEGER NOT NULL DEFAULT 1,
  clicks_count INTEGER NOT NULL DEFAULT 0,
  meta_json TEXT NOT NULL DEFAULT '{}',
  updated_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE INDEX IF NOT EXISTS idx_homepage_blocks_section ON homepage_blocks(section_key, is_published, sort_order);

